import{_ as p,a0 as a,w as s,s as d,I as i,x as l,a1 as e,A as r,ao as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"7个Linux桌面需要改进之处 | LCTT x X-CMD","titleTemplate":false,"description":"7个Linux桌面需要改进之处 | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"7个Linux桌面需要改进之处 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"7个Linux桌面需要改进之处 | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20140617 7 Improvements The Linux Desktop Needs","title":"7个Linux桌面需要改进之处","tag":"201411","desc":""},"relativePath":"201411/20140617 7 Improvements The Linux Desktop Needs.md","filePath":"[post].md"}'),u={name:"201411/20140617 7 Improvements The Linux Desktop Needs.md"};function m(x,n,f,T,L,b){const t=a("Link");return s(),d("div",null,[n[23]||(n[23]=i("h1",{id:"_7个linux桌面需要改进之处",tabindex:"-1"},[l("7个Linux桌面需要改进之处 "),i("a",{class:"header-anchor",href:"#_7个linux桌面需要改进之处","aria-label":"Permalink to “7个Linux桌面需要改进之处”"},"​")],-1)),n[24]||(n[24]=i("p",null,"在过去的15年内，Linux桌面从一个还算凑合的边缘化解决方案集合发展为一个独特的创新来源和选择之一。它的标准特点中有许多是要么不适用于Windows系统，要么就只适合作为一个专有的扩展软件。因此，使用Linux愈发变得不仅是一个原则问题，也是一种偏好。",-1)),n[25]||(n[25]=i("p",null,"然而，尽管Linux桌面不停在进步，但是仍然存在差距。一些特点正在丢失，而一些已经丢失了，还有一些令人惊喜的附加功能可以轻易地提升桌面体验，而不用挑战用户的容忍度。",-1)),n[26]||(n[26]=i("p",null,"比如说，以下是7个有利于Linux桌面发展的改善建议：",-1)),n[27]||(n[27]=i("h3",{id:"_7-简单的email加密技术",tabindex:"-1"},[l("7. 简单的Email加密技术 "),i("a",{class:"header-anchor",href:"#_7-简单的email加密技术","aria-label":"Permalink to “7. 简单的Email加密技术”"},"​")],-1)),n[28]||(n[28]=i("p",null,"如今，各种Email阅读器从Alpine到Thunderbird再到Kmail，都带有Email加密技术。然而，关于它们的文档手册通常是不存在或者非常简陋。",-1)),n[29]||(n[29]=i("p",null,"但是，即使你了解加密理论，但是使用起来仍然很困难。这些控件通常分散在配置菜单和选项卡中，需要为所有你需要和想要的设置进行一次彻底的搜索才行。如果你未能进行适当的加密设置，通常你找不到任何有用的反馈。",-1)),i("p",null,[n[1]||(n[1]=l("易用性方面最接近的是 ",-1)),e(t,{href:"https://addons.mozilla.org/en-US/thunderbird/addon/enigmail/"},{default:r(()=>[...n[0]||(n[0]=[l("Enigmail",-1)])]),_:1}),n[2]||(n[2]=l(" ，它是一个带有面向初学者的设置向导的Thunderbird扩展。但是你一定要知道怎么用Enigmail，新的加密设置菜单埋藏在撰写窗口里一级菜单下，和其他选项混在一起，这让日常用户很迷惑。",-1))]),n[30]||(n[30]=o('<p>不管是那种桌面环境，如你所知的，你应该对邮件加密，今天对安全和隐私的媒体不断报道让你知道加密有多重要。</p><h3 id="_6-虚拟工作空间缩略图" tabindex="-1">6. 虚拟工作空间缩略图 <a class="header-anchor" href="#_6-虚拟工作空间缩略图" aria-label="Permalink to “6. 虚拟工作空间缩略图”">​</a></h3><p>不需要额外的显示器，虚拟工作空间提供了更多桌面空间。然而，尽管它们很实用，但是虚拟工作空间的管理并没有在过去十年发生改变。在大多数桌面上，你能通过每个工作空间上的pager程序（一个提供很少指示除了它的名字和数字的简单矩形框）来控制它们 -- 或者，在Ubuntu的Unity 环境中，可以指出哪个工作空间是当前激活的。</p><p>确实，GNOME和Cinnamon能提供出不错的视图，但是它们的实用性受限于它们需要显示屏大小的事实。而 KDE 写出内容列表则和主流的图形桌面不太协调。</p><p>一个比较不错的解决方案应该是鼠标悬停在足够大的缩略图上来获取正常的视图，这样就精确地查看每个工作空间上的东西了。</p><h3 id="_5-一个合用的菜单" tabindex="-1">5. 一个合用的菜单 <a class="header-anchor" href="#_5-一个合用的菜单" aria-label="Permalink to “5. 一个合用的菜单”">​</a></h3><p>现代型桌面很久之前就已经舍弃了级联子菜单铺满整个桌面的经典型菜单了。如今，一般的电脑都有太多的应用程序以至于不能适应这样的模式。</p><p>糟糕的是，没有什么主要的替代品能与经典型菜单一样方便。把菜单根植于一个单一的窗口，其效果是不理想的，因为你要么必须截掉子菜单要么就用鼠标不断地调整窗口大小。</p><p>但是全屏幕菜单的产品还要差，这意味着你甚至要在开始工作之前就调整屏幕，并且哪个搜索框其实只在你已经知道什么应用程序可用的情况下才有用 -- 这种情况下你还不如直接用命令行。</p><p>坦白地说，我不知道拿什么来解决这个问题，OS X下的spinner racks吗？我可以肯定地说，所有现代型菜单产品在桌面上呈现出一个个精心构造的图标似乎更是一个合理的选择。</p><h3 id="_4-一个专业的、实惠的视频编辑器" tabindex="-1">4. 一个专业的、实惠的视频编辑器 <a class="header-anchor" href="#_4-一个专业的、实惠的视频编辑器" aria-label="Permalink to “4. 一个专业的、实惠的视频编辑器”">​</a></h3><p>多年来，Linux已经慢慢地填充了软件生产力上的空白。然而即便如此，它仍然缺少价格合理的视频编辑软件。</p>',12)),i("p",null,[n[4]||(n[4]=l("问题不在于没有这样的自由软件。",-1)),e(t,{href:"http://en.wikipedia.org/wiki/Autodesk_Maya"},{default:r(()=>[...n[3]||(n[3]=[l("Maya",-1)])]),_:1}),n[5]||(n[5]=l(" 是动画产业的标准之一，但是问题在于这样的软件的售价达数千美金。",-1))]),n[31]||(n[31]=i("p",null,"另一边，比如Pitivi或者是Blender这样的免费软件, 它们的功能性 -- 尽管它们的开发者足够的努力 -- 只能保证基本功能。虽然取得了进步，但还是和用户们所期望的相去甚远。",-1)),n[32]||(n[32]=i("p",null,"尽管我听说一些非主流的厂家使用的是原生态Linux视频编辑器，原因通常是因为他们抱怨其它编辑器不好，但其余的人更愿意减少麻烦，从而在其它操作系统上对视频进行编辑。",-1)),n[33]||(n[33]=i("h3",{id:"_3-一个文档处理器",tabindex:"-1"},[l("3. 一个文档处理器 "),i("a",{class:"header-anchor",href:"#_3-一个文档处理器","aria-label":"Permalink to “3. 一个文档处理器”"},"​")],-1)),n[34]||(n[34]=i("p",null,"有一个极端是，那些需要进行文字处理的用户，Google Docs就让他们满意了；而另一个极端是对于那些排版设计的专家来说，Scribus是唯一比较可行的应用。",-1)),i("p",null,[n[7]||(n[7]=l("这两种极端之间还有一层，是那些比如那些写作很长的文本的文件的出版商和作家。这类用户有些是由基于Windows的 ",-1)),e(t,{href:"http://www.adobe.com/products/framemaker.html"},{default:r(()=>[...n[6]||(n[6]=[l("Adobe FrameMaker",-1)])]),_:1}),n[8]||(n[8]=l(" 来服务, 有些则由基于Linux的LibreOffice Writer来服务。",-1))]),n[35]||(n[35]=o('<p>不幸的是，这些用户显然不会优先考虑LibreOffice，Calligra Words， AbiWord或者是任何其它的办公套件。应该提供给用户的办公套件的特色功能包括：</p><ul><li>为每个文件建立引用书目数据库。</li><li>表格的样式能和段落与字符保持一致。</li><li>除了页眉和页脚，带有持续性内容的页面样式，在每次使用样式时都一样。</li><li>交叉引用存储格式，以便不需要每次都手动创建。</li></ul><p>无论是LibreOffice还是其它同类应用，提供这些特色功能与它们是否可用是并不相干的。但是没有它们，Linux桌面对于一群潜在的用户来说就是个不完善的东西。</p><h3 id="_2-彩色标题栏" tabindex="-1">2.彩色标题栏 <a class="header-anchor" href="#_2-彩色标题栏" aria-label="Permalink to “2.彩色标题栏”">​</a></h3><p>浏览器的扩展软件向我们展示了彩色编码标签对于工作空间的作用。打开了八九个标签后，它的标题栏就看不全了，所以颜色通常是最快区分标签关系的方法。</p><p>同样的系统也能用到桌面上。更好的是，彩色编码也许可以按会话保存，允许用户同时打开某个任务所需的所有应用。到目前为止，我知道没有任何一个桌面有这个特点。</p><h3 id="_1-图标栏" tabindex="-1">1. 图标栏 <a class="header-anchor" href="#_1-图标栏" aria-label="Permalink to “1. 图标栏”">​</a></h3>',7)),i("p",null,[n[10]||(n[10]=l("多年以来，Stardock公司一直销售着一个名叫 ",-1)),e(t,{href:"http://www.stardock.com/products/fences/"},{default:r(()=>[...n[9]||(n[9]=[l("Fences",-1)])]),_:1}),n[11]||(n[11]=l(" 的扩展软件,它用来分类和组织桌面上的图标，你能用它给每个组取名并且可以把每个图标都放在一起。另外，你可以指定不同的文件类型自动加入到一个组里，并且按个人需要来隐藏和整理。",-1))]),n[36]||(n[36]=i("p",null,"换句话说，fences让用户整天在桌面上干的事情自动有序地分组排列。然而，除了一两个小功能与KDE的文件夹视图类似之外，fences的功能仍然没有出现在Linux桌面上。这也许是因为开发人员把注意力放到移动设备上作为灵感来源，而使用fences无疑是传统工作站桌面的一大特征。",-1)),n[37]||(n[37]=i("h3",{id:"我个人的列表",tabindex:"-1"},[l("我个人的列表 "),i("a",{class:"header-anchor",href:"#我个人的列表","aria-label":"Permalink to “我个人的列表”"},"​")],-1)),n[38]||(n[38]=i("p",null,"我做了这种列表之后，让我震惊的是这些不多的改进都是普适性的，其中几项改进将会吸引大量特定的用户，只有一个是来自专有软件的移植，其中一个至少是修饰性的而不是功能性的。",-1)),n[39]||(n[39]=i("p",null,"这一观察表明，对于普通用户来说，Linux能添加的功能已经所剩无几了。作为一个通用的桌面，Linux从几年前到现在都很多元化，到今天，用户能从超过半打的主流桌面中选择出一个来使用。",-1)),n[40]||(n[40]=i("p",null,"当然这不意味着，一些专家就不会有其它意见。另外，没有人会关心不断变化的需求会不会使改进令人满意。但是它意味着这份充斥着改进建议的名单上的许多项目将会高度个人化。",-1)),n[41]||(n[41]=i("p",null,"所有这些都是为了抛砖引玉：你认为还有什么其它的对桌面有益的建议吗？",-1)),n[42]||(n[42]=i("hr",null,null,-1)),i("p",null,[n[13]||(n[13]=l("via: ",-1)),e(t,{href:"http://www.datamation.com/open-source/7-improvements-the-linux-desktop-needs-1.html"},{default:r(()=>[...n[12]||(n[12]=[l("http://www.datamation.com/open-source/7-improvements-the-linux-desktop-needs-1.html",-1)])]),_:1})]),i("p",null,[n[16]||(n[16]=l("译者：",-1)),e(t,{href:"https://github.com/ZTinoZ"},{default:r(()=>[...n[14]||(n[14]=[l("ZTinoZ",-1)])]),_:1}),n[17]||(n[17]=l(" 校对：",-1)),e(t,{href:"https://github.com/wxy"},{default:r(()=>[...n[15]||(n[15]=[l("wxy",-1)])]),_:1})]),i("p",null,[n[20]||(n[20]=l("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...n[18]||(n[18]=[l("LCTT",-1)])]),_:1}),n[21]||(n[21]=l(" 原创翻译，",-1)),e(t,{href:"http://linux.cn/"},{default:r(()=>[...n[19]||(n[19]=[l("Linux中国",-1)])]),_:1}),n[22]||(n[22]=l(" 荣誉推出",-1))])])}const P=p(u,[["render",m]]);export{C as __pageData,P as default};
